button {
  background: #1d4ed8;
  color: white;
  border: none;
  padding: 0.6rem 1.2rem;
  border-radius: 6px;
  transition: background-color 200ms ease-out, transform 200ms ease-out;
}

button:hover {
  background: #1e3a8a;
  transform: translateY(-2px);
}

a {
  transition: color 150ms;
}

a:hover {
  color: #dc2626;
}
